void handle_outbound_pinhole_timeout(struct upnphttp *h, const char *action, const char *ns) {
    if (!ipv6_forwarding_enabled()) {
        upnphttp_send_error(h, 403, "IPv6 forwarding is disabled");
        return;
    }

    char *internal_client_ip = NULL;
    char *internal_port = NULL;
    char *external_port = NULL;
    char *remote_host = NULL;
    char *protocol = NULL;

    if (!upnphttp_get_request_var(h, "InternalClient", &internal_client_ip) ||
        !upnphttp_get_request_var(h, "InternalPort", &internal_port) ||
        !upnphttp_get_request_var(h, "ExternalPort", &external_port) ||
        !upnphttp_get_request_var(h, "RemoteHost", &remote_host) ||
        !upnphttp_get_request_var(h, "Protocol", &protocol)) {
        upnphttp_send_error(h, 400, "Missing required parameters");
        return;
    }

    log_request_details(internal_client_ip, internal_port, external_port, remote_host, protocol);

    int timeout = check_outbound_pinhole_timeout(internal_client_ip, internal_port, remote_host, protocol);
    if (timeout < 0) {
        upnphttp_send_error(h, 500, "Failed to check pinhole timeout or unsupported protocol");
        return;
    }

    char soap_response[1024];
    snprintf(soap_response, sizeof(soap_response),
             "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\">"
             "<s:Body><u:%s xmlns:u=\"%s\">"
             "<NewTimeout>%d</NewTimeout>"
             "</u:%s></s:Body></s:Envelope>",
             action, ns, timeout, action);

    upnphttp_send_response(h, 200, "OK", "text/xml; charset=\"utf-8\"", soap_response, strlen(soap_response));
}

